<#
.SYNOPSIS
    Erzeugt aus dem JSON-Schema von atlas.json die Doku, die Einstellungstabelle
    und die Schema-Unit des Plugins und prüft den Parser dagegen.

.DESCRIPTION
    Einzige Quelle ist schemas/atlas.schema.json (#265):
    - docs/Konfiguration.md: jeder Schlüssel mit Typ, Standardwert, erlaubten
      Werten und Beschreibung; verschachtelte Objekte als eigener Abschnitt.
    - docs/en/Configuration.md (#1458): dieselbe Doku auf Englisch aus
      x-description-en. Wächter: Jede description im Schema hat ein nicht
      leeres x-description-en (das Plugin zeigt es bei englischer IDE).
    - docs/Einstellungen.md: Tabelle für das Einstellungs-Plugin (#227) aus den
      Angaben x-page, x-control, x-issue, x-commandLine und x-restart.
      x-quickToggle (mit x-plugin, x-caption, x-captionEn) an einer booleschen
      Einstellung macht sie zum Schnellschalter im Plugin (#604).
    - docs/en/Settings.md (#1458): dieselbe Tabelle auf Englisch; Seitennamen wie in
      Atlas.Core.Settings.PageNames, Bedienelemente und die Zeilen von Hand aus
      englischen Gegenstücken im Skript (gleiche Anzahl, sonst Abbruch).
    - x-experimental (#834) an einer Einstellung beider Schemata: experimentelle
      Funktion, Kennzeichen in Konfiguration.md und Einstellungen.md (Abschnitt
      „Experimentelle Funktionen“), Liste ExperimentalSettingPaths in ScopeData.
      Wächter: Vorgabe aus (false bzw. x-offValue), nie am Hauptschalter
      experimental.enabled, nie an einem ganzen Objekt; Profil „Alles an“ lässt
      sie aus, Profil „Alles an, auch experimentell“ schaltet alle ein.
    - Wächter: Die Abschnitte in Atlas.Common.Configuration.Internals.*Options
      (je Abschnitt Lesen und Schichten) müssen genau den Schlüsseln im Schema entsprechen.
    - Atlas.Common.Configuration.Internals.ScopeData: Ort jedes Schlüssels aus
      x-scope ("global" = %APPDATA%\Atlas\settings.json, "project" = atlas.json,
      "both" = an beiden Orten, das Projekt übersteuert je Glied; steht in beiden Listen).
      Jeder Schlüssel der obersten Ebene braucht x-scope; ein Glied darf mit
      eigenem x-scope abweichen (gemischtes Objekt wie index, completion).

    - schemas/atlas-plugin.schema.json: Katalog der Plugin-Einstellungen mit
      x-key, x-area, x-page (#723). Wächter: genau die Namen aus
      TAtlasPluginSettings.Save, Bereiche aus x-areas, x-key eindeutig. Jeder
      globale Schlüssel in atlas.schema.json braucht x-area. Daraus entstehen
      Atlas.Core.Settings.PluginSchemaData, der Abschnitt „Bereiche für Export,
      Import und Zurücksetzen“ in Einstellungen.md und aus Setup/Profile/*.json
      die Unit Atlas.Core.Settings.ProfileData (eingebaute Profile).
    - Gruppen der Optionsseite (#890): x-parent (x-key des Hauptschalters, ""
      = keiner, sonst Präfixregel) und x-node (Kennung aus x-nodes, "" =
      Hauptknoten, sonst vom Hauptschalter geerbt). Wächter: x-parent bekannt
      und boolesch, keine Zyklen, x-node bekannt, ein Knoten nur auf einer
      x-page, kein Knoten ohne Einstellungen. Einstellungen.md bekommt den
      Abschnitt „Optionsseite: Unterpunkte und Hauptschalter“.

    Mit -Check wird nichts geschrieben; Exit-Code 1, wenn eine Datei veraltet ist
    oder der Parser abweicht.

    Pflegeregel: Neue Einstellung -> Schema (mit x-page, x-control, x-issue),
    Parser, Test; dann dieses Skript ausführen.

.EXAMPLE
    pwsh Tools/Update-ConfigDoc.ps1
    pwsh Tools/Update-ConfigDoc.ps1 -Check
#>
[CmdletBinding()]
param(
    [string] $Root = (Split-Path -Parent $PSScriptRoot),
    [switch] $Check
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$SchemaPath = Join-Path $Root 'schemas/atlas.schema.json'
$DocPath = Join-Path $Root 'docs/Konfiguration.md'
$DocEnPath = Join-Path $Root 'docs/en/Configuration.md'
$TablePath = Join-Path $Root 'docs/Einstellungen.md'
$TableEnPath = Join-Path $Root 'docs/en/Settings.md'
$ParserPath = Join-Path $Root 'Packages/Atlas.Common/Source/Configuration/Atlas.Common.Configuration.Parser.pas'
$Utf8 = New-Object System.Text.UTF8Encoding($false)

$Schema = Get-Content -Raw -Encoding utf8 $SchemaPath | ConvertFrom-Json -AsHashtable
$PluginSchemaPath = Join-Path $Root 'schemas/atlas-plugin.schema.json'
$PluginSchema = Get-Content -Raw -Encoding utf8 $PluginSchemaPath | ConvertFrom-Json -AsHashtable
# TAtlasPluginSettings und seine Bereichs-Units Atlas.Core.Settings.Plugin.<Bereich> (Records je x-area).
$PluginFolder = Join-Path $Root 'Packages/Atlas.IDE.Base/Source/Core/Settings'
$ProfileFolder = Join-Path $Root 'Setup/Profile'

function Has([hashtable] $Node, [string] $Key) { $Node.ContainsKey($Key) -and $null -ne $Node[$Key] }

function Format-Value($Value) {
    if ($Value -is [bool]) { return '`' + $Value.ToString().ToLowerInvariant() + '`' }
    if ($Value -is [string]) { return '`"' + $Value + '"`' }
    return '`' + ($Value | ConvertTo-Json -Compress) + '`'
}

function Escape([string] $Text) { $Text.Replace('|', '\|').Replace("`r", '').Replace("`n", ' ') }

# Experimentelle Funktionen (#834)
$MasterPath = 'experimental.enabled'
$ExperimentalNote = 'Experimentell (Vorgabe aus; wirkt nur mit `experimental.enabled`). '
$ExperimentalNoteEn = 'Experimental (off by default; only active with `experimental.enabled`). '
function Is-Experimental([hashtable] $Node) { (Has $Node 'x-experimental') -and ($Node['x-experimental'] -eq $true) }
$ServerExperimental = New-Object System.Collections.Generic.List[string]
foreach ($Name in $Schema['properties'].Keys) {
    if ($Name -eq '$schema') { continue }
    $P = $Schema['properties'][$Name]
    if (Is-Experimental $P) { $ServerExperimental.Add($Name) }
    if (Has $P 'properties') {
        foreach ($Sub in $P['properties'].Keys) { if (Is-Experimental $P['properties'][$Sub]) { $ServerExperimental.Add("$Name.$Sub") } }
    }
}
$PluginExperimental = New-Object System.Collections.Generic.List[string]
foreach ($Name in $PluginSchema['properties'].Keys) { if (Is-Experimental $PluginSchema['properties'][$Name]) { $PluginExperimental.Add($Name) } }

# Ort eines Schlüssels: eigenes x-scope, sonst das des Objekts.
function Scope-Of([hashtable] $Node, [string] $Inherited) { if (Has $Node 'x-scope') { $Node['x-scope'] } else { $Inherited } }

# Sprache der Doku (#1458): $script:En wählt englische Texte und x-description-en.
$script:En = $false
function Scope-Text([string] $Scope) {
    if ($script:En) {
        if ($Scope -eq 'global') { return 'global (settings.json)' }
        if ($Scope -eq 'project') { return 'project (atlas.json)' }
        if ($Scope -eq 'both') { return 'global and project' }
        return ''
    }
    if ($Scope -eq 'global') { return 'global (settings.json)' }
    if ($Scope -eq 'project') { return 'Projekt (atlas.json)' }
    if ($Scope -eq 'both') { return 'global und Projekt' }
    return ''
}

# Beschreibung in der Sprache der Doku; englisch ohne x-description-en die deutsche (meldet der Wächter).
function Description-Of([hashtable] $Node) {
    if ($script:En -and (Has $Node 'x-description-en')) { return $Node['x-description-en'] }
    if (Has $Node 'description') { return $Node['description'] }
    return ''
}

function Write-Table([System.Text.StringBuilder] $Out, [hashtable] $Properties, [string] $Prefix, [string] $ParentScope) {
    if ($script:En) { [void]$Out.AppendLine('| Key | Place | Type | Default | Values | Meaning |') }
    else { [void]$Out.AppendLine('| Schlüssel | Ort | Typ | Standard | Werte | Bedeutung |') }
    [void]$Out.AppendLine('|---|---|---|---|---|---|')
    foreach ($Name in $Properties.Keys) {
        if ($Name -eq '$schema') { continue }
        $P = $Properties[$Name]
        $Type = if (Has $P 'type') { $P['type'] } else { '' }
        if ($Type -eq 'array' -and (Has $P 'items') -and (Has $P['items'] 'type')) { $Type = "array<$($P['items']['type'])>" }
        $Default = if ($P.ContainsKey('default')) { Format-Value $P['default'] } else { '–' }
        $Values = if (Has $P 'enum') { ($P['enum'] | ForEach-Object { Format-Value $_ }) -join ', ' }
                  elseif (Has $P 'examples') { $(if ($script:En) { 'e.g. ' } else { 'z. B. ' }) + (($P['examples'] | ForEach-Object { Format-Value $_ }) -join ', ') }
                  elseif ((Has $P 'minimum') -or (Has $P 'maximum')) { "$(if (Has $P 'minimum') { $P['minimum'] } else { '' })…$(if (Has $P 'maximum') { $P['maximum'] } else { '' })" }
                  else { '' }
        $Description = Escape (Description-Of $P)
        $Note = if ($script:En) { $ExperimentalNoteEn } else { $ExperimentalNote }
        if (Is-Experimental $P) { $Description = "**$($Note.TrimEnd())** $Description" }
        $Place = Scope-Text (Scope-Of $P $ParentScope)
        if (Has $P 'properties') {
            $Inner = @($P['properties'].Values | ForEach-Object { Scope-Of $_ (Scope-Of $P $ParentScope) } | Sort-Object -Unique)
            if ($Inner.Count -gt 1) { $Place = $(if ($script:En) { 'mixed, see below' } else { 'gemischt, siehe unten' }) }
        }
        [void]$Out.AppendLine("| ``$Prefix$Name`` | $Place | $Type | $Default | $Values | $Description |")
    }
}

$Out = New-Object System.Text.StringBuilder
[void]$Out.AppendLine('# Konfiguration: atlas.json')
[void]$Out.AppendLine()
[void]$Out.AppendLine('<!-- Erzeugt von Tools/Update-ConfigDoc.ps1 aus schemas/atlas.schema.json. Nicht von Hand bearbeiten. -->')
[void]$Out.AppendLine()
[void]$Out.AppendLine((Escape $Schema['description']))
[void]$Out.AppendLine()
[void]$Out.AppendLine('Jeder Schlüssel hat genau einen Ort (Spalte „Ort“): Projekt-Schlüssel stehen in `atlas.json` im Projektordner (im Plugin *Atlas › Projekt-Einstellungen*), globale in `%APPDATA%\Atlas\settings.json` für alle Projekte (im Plugin *Tools › Optionen › Atlas*). Ausnahme `rules`: Prüfregeln gehen an beiden Orten, global für alle Projekte, `atlas.json` übersteuert je Regel. Ein Schlüssel am falschen Ort wird ignoriert und als Warnung gemeldet. Fehlende Schlüssel nehmen den Standardwert. In der IDE bestimmt die laufende IDE die Delphi-Version (`delphiVersion` gilt dort nicht). Die Prüfregeln stehen in [Regeln.md](Regeln.md).')
[void]$Out.AppendLine()
[void]$Out.AppendLine('`atlas.json` liegt im Repository und gilt für alle im Team (#486). Zugangsdaten (Schlüssel wie `token`, `password`, `user` auf jeder Ebene, Adressen wie `https://user:pw@…` oder `?token=…`) und absolute Pfade (Laufwerk oder UNC) in den Pfad-Einstellungen (`project`, `testUnits.folder`, `testUnits.project`, `exclude`, `index.exclude`, `overrides[].files`) werden beim Lesen ignoriert und als Warnung gemeldet. Glob-Muster ab dem Projektordner (`/Generated/**`) und relative Pfade (`..\Tests`) bleiben erlaubt. Die globale `settings.json` ist persönlich und davon ausgenommen. Die Team-Einstellungen des Plugins stehen in der eigenen Projektdatei `.atlas` (siehe [Einstellungen.md](Einstellungen.md)).')
[void]$Out.AppendLine()
[void]$Out.AppendLine('## Schlüssel')
[void]$Out.AppendLine()
Write-Table $Out $Schema['properties'] '' ''
foreach ($Name in $Schema['properties'].Keys) {
    $P = $Schema['properties'][$Name]
    if ((Has $P 'properties')) {
        [void]$Out.AppendLine()
        [void]$Out.AppendLine("## $Name")
        [void]$Out.AppendLine()
        Write-Table $Out $P['properties'] "$Name." (Scope-Of $P '')
    }
}
[void]$Out.AppendLine()
[void]$Out.AppendLine('## Beispiel')
[void]$Out.AppendLine()
[void]$Out.AppendLine('```json')
[void]$Out.AppendLine('{')
[void]$Out.AppendLine('  "$schema": "https://raw.githubusercontent.com/xKnockOut/Atlas/main/schemas/atlas.schema.json",')
[void]$Out.AppendLine('  "project": "App.dproj",')
[void]$Out.AppendLine('  "config": "Debug",')
[void]$Out.AppendLine('  "platform": "Win64",')
[void]$Out.AppendLine('  "rules": { "empty-except": "error" },')
[void]$Out.AppendLine('  "exclude": ["ThirdParty/**"]')
[void]$Out.AppendLine('}')
[void]$Out.AppendLine('```')
$Text = $Out.ToString().Replace("`r`n", "`n")

# --- Englische Doku (#1458) ---
$script:En = $true
$Out = New-Object System.Text.StringBuilder
[void]$Out.AppendLine('# Configuration: atlas.json')
[void]$Out.AppendLine()
[void]$Out.AppendLine('<!-- Generated by Tools/Update-ConfigDoc.ps1 from schemas/atlas.schema.json. Do not edit by hand. -->')
[void]$Out.AppendLine()
[void]$Out.AppendLine((Escape (Description-Of $Schema)))
[void]$Out.AppendLine()
[void]$Out.AppendLine('Each key has exactly one place (column "Place"): project keys live in `atlas.json` in the project folder (in the plugin *Atlas › Project settings*), global keys in `%APPDATA%\Atlas\settings.json` for all projects (in the plugin *Tools › Options › Atlas*). Exception `rules`: check rules work in both places, globally for all projects, `atlas.json` overrides per rule. A key in the wrong place is ignored and reported as a warning. Missing keys take the default value. In the IDE the running IDE determines the Delphi version (`delphiVersion` does not apply there). The check rules are described in [Regeln.md](../Regeln.md) (German). The German version of this page is [Konfiguration.md](../Konfiguration.md).')
[void]$Out.AppendLine()
[void]$Out.AppendLine('`atlas.json` lives in the repository and applies to everyone in the team (#486). Credentials (keys such as `token`, `password`, `user` on any level, addresses such as `https://user:pw@…` or `?token=…`) and absolute paths (drive or UNC) in the path settings (`project`, `testUnits.folder`, `testUnits.project`, `exclude`, `index.exclude`, `overrides[].files`) are ignored when reading and reported as a warning. Glob patterns from the project folder (`/Generated/**`) and relative paths (`..\Tests`) stay allowed. The global `settings.json` is personal and exempt from this. The team settings of the plugin live in the separate project file `.atlas`.')
[void]$Out.AppendLine()
[void]$Out.AppendLine('The language of findings, light bulb, hover and settings follows the IDE (#1458): `language` `""` takes the language of the client (Delphi IDE: its language, otherwise English), `"de"` and `"en"` fix it. `AtlasServer --check` takes `--locale de|en`.')
[void]$Out.AppendLine()
[void]$Out.AppendLine('## Keys')
[void]$Out.AppendLine()
Write-Table $Out $Schema['properties'] '' ''
foreach ($Name in $Schema['properties'].Keys) {
    $P = $Schema['properties'][$Name]
    if ((Has $P 'properties')) {
        [void]$Out.AppendLine()
        [void]$Out.AppendLine("## $Name")
        [void]$Out.AppendLine()
        Write-Table $Out $P['properties'] "$Name." (Scope-Of $P '')
    }
}
[void]$Out.AppendLine()
[void]$Out.AppendLine('## Example')
[void]$Out.AppendLine()
[void]$Out.AppendLine('```json')
[void]$Out.AppendLine('{')
[void]$Out.AppendLine('  "$schema": "https://raw.githubusercontent.com/xKnockOut/Atlas/main/schemas/atlas.schema.json",')
[void]$Out.AppendLine('  "project": "App.dproj",')
[void]$Out.AppendLine('  "config": "Debug",')
[void]$Out.AppendLine('  "platform": "Win64",')
[void]$Out.AppendLine('  "rules": { "empty-except": "error" },')
[void]$Out.AppendLine('  "exclude": ["ThirdParty/**"]')
[void]$Out.AppendLine('}')
[void]$Out.AppendLine('```')
$TextEn = $Out.ToString().Replace("`r`n", "`n")
$script:En = $false

