# --- Bereiche für Export, Import und Zurücksetzen (#723) ---
$AreaKeys = [ordered]@{}
foreach ($Area in $PluginSchema['x-areas'].PSBase.Keys) { $AreaKeys[$Area] = New-Object System.Collections.Generic.List[string] }
$Skipped = New-Object System.Collections.Generic.List[string]
$PluginKeys = @{}
foreach ($Name in $PluginSchema['properties'].Keys) {
    $P = $PluginSchema['properties'][$Name]
    if (-not (Has $P 'x-key')) { continue }
    $PluginKeys[$P['x-key']] = $Name
    if (((Has $P 'x-state') -and $P['x-state']) -or ((Has $P 'x-machine') -and $P['x-machine'])) { $Skipped.Add('`' + $P['x-key'] + '`'); continue }
    if ((Has $P 'x-area') -and $AreaKeys.Contains($P['x-area'])) { $AreaKeys[$P['x-area']].Add('`' + $P['x-key'] + '`') }
}
foreach ($Name in $Schema['properties'].Keys) {
    if ($Name -eq '$schema') { continue }
    $P = $Schema['properties'][$Name]
    $Scope = Scope-Of $P ''
    $Leaves = @()
    if (Has $P 'properties') {
        foreach ($Sub in $P['properties'].Keys) {
            $S = $P['properties'][$Sub]
            if ('global', 'both' -cnotcontains (Scope-Of $S $Scope)) { continue }
            $Area = if (Has $S 'x-area') { $S['x-area'] } elseif (Has $P 'x-area') { $P['x-area'] } else { '' }
            $Leaves += , @("$Name.$Sub", $Area, ((Has $S 'x-machine') -or (Has $P 'x-machine')))
        }
    }
    elseif ('global', 'both' -ccontains $Scope) {
        $Area = if (Has $P 'x-area') { $P['x-area'] } else { '' }
        $Leaves += , @($Name, $Area, (Has $P 'x-machine'))
    }
    foreach ($Leaf in $Leaves) {
        if ($PluginKeys.ContainsKey($Leaf[0])) { continue }
        if ($Leaf[2]) { $Skipped.Add('`' + $Leaf[0] + '`'); continue }
        if ($AreaKeys.Contains($Leaf[1])) { $AreaKeys[$Leaf[1]].Add('`' + $Leaf[0] + '`') }
    }
}
# --- Optionsseite: Unterpunkte und Hauptschalter (#890) ---
# Wie Atlas.Core.Settings.Groups: Hauptschalter aus x-parent (x-key eines booleschen Schalters, "" = keiner),
# sonst Präfixregel (längstes Präfix P mit boolescher Einstellung P oder P.enabled, nie die Einstellung selbst);
# Unterpunkt aus x-node (Kennung aus x-nodes, "" = Hauptknoten), sonst vom nächsten Hauptschalter geerbt.
$GroupIssues = New-Object System.Collections.Generic.List[string]
$PluginProps = $PluginSchema['properties']
$NodeTable = if (Has $PluginSchema 'x-nodes') { $PluginSchema['x-nodes'] } else { @{} }
$KeyNames = @{}
foreach ($Name in $PluginProps.Keys) { $KeyNames[$PluginProps[$Name]['x-key']] = $Name }
function Is-Switch([string] $Key) { $KeyNames.ContainsKey($Key) -and ($PluginProps[$KeyNames[$Key]]['type'] -ceq 'boolean') }
$Parents = @{}
foreach ($Name in $PluginProps.Keys) {
    $P = $PluginProps[$Name]
    $Key = [string]$P['x-key']
    $Parent = ''
    if ($P.ContainsKey('x-parent')) {
        $Wanted = [string]$P['x-parent']
        if ($Wanted -ne '') {
            if (-not $KeyNames.ContainsKey($Wanted)) { $GroupIssues.Add("Plugin-Katalog: ""$Name"" mit unbekanntem Hauptschalter x-parent ""$Wanted""") }
            elseif (-not (Is-Switch $Wanted)) { $GroupIssues.Add("Plugin-Katalog: ""$Name"": Hauptschalter x-parent ""$Wanted"" ist nicht boolesch") }
            else { $Parent = $KeyNames[$Wanted] }
        }
    }
    else {
        $Prefix = $Key
        while ($Prefix.Contains('.') -and ($Parent -eq '')) {
            $Prefix = $Prefix.Substring(0, $Prefix.LastIndexOf('.'))
            foreach ($Candidate in $Prefix, "$Prefix.enabled") {
                if (($Parent -eq '') -and ($Candidate -cne $Key) -and (Is-Switch $Candidate)) { $Parent = $KeyNames[$Candidate] }
            }
        }
    }
    $Parents[$Name] = $Parent
}
foreach ($Name in $PluginProps.Keys) {
    $Seen = New-Object System.Collections.Generic.List[string]
    $Seen.Add($Name)
    $Current = $Parents[$Name]
    while (($Current -ne '') -and -not $Seen.Contains($Current)) { $Seen.Add($Current); $Current = $Parents[$Current] }
    if ($Current -ceq $Name) {
        $Chain = (@($Seen | ForEach-Object { $PluginProps[$_]['x-key'] }) + @($PluginProps[$Name]['x-key'])) -join ' → '
        $GroupIssues.Add("Plugin-Katalog: Zyklus über x-parent: $Chain")
        $Parents[$Name] = ''
    }
}
function Node-Of([string] $Name) {
    $Current = $Name
    while ($Current -ne '') {
        if ($PluginProps[$Current].ContainsKey('x-node')) { return [string]$PluginProps[$Current]['x-node'] }
        $Current = $Parents[$Current]
    }
    return ''
}
$NodePages = @{}
$UsedNodes = @{}
foreach ($Name in $PluginProps.Keys) {
    $P = $PluginProps[$Name]
    if ((Has $P 'x-node') -and ([string]$P['x-node'] -ne '') -and -not $NodeTable.Contains([string]$P['x-node'])) {
        $GroupIssues.Add("Plugin-Katalog: ""$Name"" mit unbekanntem Unterpunkt x-node ""$($P['x-node'])""")
    }
    $Node = Node-Of $Name
    if ($Node -eq '') { continue }
    $UsedNodes[$Node] = $true
    if ($NodePages.ContainsKey($Node) -and ($NodePages[$Node] -cne $P['x-page'])) {
        $GroupIssues.Add("Plugin-Katalog: Unterpunkt ""$Node"" auf zwei Seiten ($($NodePages[$Node]), $($P['x-page'])); ""$Name"" braucht x-node """" oder dieselbe Seite")
    }
    elseif (-not $NodePages.ContainsKey($Node)) { $NodePages[$Node] = $P['x-page'] }
}
foreach ($Node in $NodeTable.Keys) { if (-not $UsedNodes.ContainsKey($Node)) { $GroupIssues.Add("Plugin-Katalog: Unterpunkt ""$Node"" in x-nodes ohne Einstellung") } }

function Write-Group([string] $Name, [string] $Node, [int] $Depth) {
    $P = $PluginProps[$Name]
    $Line = ('  ' * $Depth) + '- `' + $P['x-key'] + '`'
    if (Is-Experimental $P) { $Line += (Tr ' (experimentell)' ' (experimental)') }
    $Parent = $Parents[$Name]
    if (($Depth -eq 1) -and ($Parent -ne '')) { $Line += (Tr ' – hängt an `' ' – depends on `') + $PluginProps[$Parent]['x-key'] + '`' }
    [void]$Table.AppendLine($Line)
    foreach ($Child in $PluginProps.Keys) {
        if (($Parents[$Child] -ceq $Name) -and ((Node-Of $Child) -ceq $Node) -and ($PluginProps[$Child]['x-page'] -ceq $P['x-page']) -and -not ((Has $PluginProps[$Child] 'x-state') -and $PluginProps[$Child]['x-state'])) {
            Write-Group $Child $Node ($Depth + 1)
        }
    }
}
$PageOrder = New-Object System.Collections.Generic.List[string]
foreach ($Name in $PluginProps.Keys) { if (-not $PageOrder.Contains([string]$PluginProps[$Name]['x-page'])) { $PageOrder.Add([string]$PluginProps[$Name]['x-page']) } }

# Einstellungen.md bzw. en/Settings.md in der Sprache von $script:En.
function Build-SettingsTable {
    $Table = New-Object System.Text.StringBuilder
    if ($script:En) {
        [void]$Table.AppendLine('# Settings')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('*Deutsche Fassung: [Einstellungen.md](../Einstellungen.md)*')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('<!-- Generated by Tools/Update-ConfigDoc.ps1 from schemas/atlas.schema.json. Do not edit by hand. -->')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('All settings with page and control in the settings plugin (#227). Details on values and meaning are in [Configuration.md](Configuration.md).')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('| Page | Setting | Default | Source | Restart | Control | Origin |')
    }
    else {
        [void]$Table.AppendLine('# Einstellungen')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('*English version: [en/Settings.md](en/Settings.md)*')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('<!-- Erzeugt von Tools/Update-ConfigDoc.ps1 aus schemas/atlas.schema.json. Nicht von Hand bearbeiten. -->')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('Alle Einstellungen mit Seite und Bedienelement im Einstellungs-Plugin (#227). Einzelheiten zu Werten und Bedeutung stehen in [Konfiguration.md](Konfiguration.md).')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('| Seite | Einstellung | Standard | Quelle | Neustart | Bedienelement | Herkunft |')
    }
    [void]$Table.AppendLine('|---|---|---|---|---|---|---|')
    $Experimental = Tr ' (experimentell)' ' (experimental)'
    $GlobalSource = Tr 'settings.json (Tools › Optionen › Atlas)' 'settings.json (Tools › Options › Atlas)'
    $ProjectSource = Tr 'atlas.json (Atlas › Projekt-Einstellungen)' 'atlas.json (Atlas › Project settings)'
    foreach ($Name in $Schema['properties'].Keys) {
        if ($Name -eq '$schema') { continue }
        $P = $Schema['properties'][$Name]
        $Setting = '`' + $Name + '`'
        if (Is-Experimental $P) { $Setting += $Experimental }
        if (Has $P 'properties') { $Setting += ': ' + (($P['properties'].Keys | ForEach-Object { if (Is-Experimental $P['properties'][$_]) { '`' + $_ + '`' + $Experimental } else { '`' + $_ + '`' } }) -join ', ') }
        $Default = if ($P.ContainsKey('default')) { Format-Value $P['default'] } else { '–' }
        $Scope = Scope-Of $P ''
        $Source = if ($Scope -eq 'global') { $GlobalSource } elseif ($Scope -eq 'both') { $GlobalSource + (Tr ' und ' ' and ') + $ProjectSource } else { $ProjectSource }
        if (Has $P 'properties') {
            $Other = @($P['properties'].Keys | Where-Object { (Scope-Of $P['properties'][$_] $Scope) -ne $Scope })
            if ($Other.Count -gt 0) {
                $OtherFile = if ($Scope -eq 'global') { 'atlas.json' } else { 'settings.json' }
                $Source += '; ' + (($Other | ForEach-Object { '`' + $_ + '`' }) -join ', ') + " in $OtherFile"
            }
        }
        if (Has $P 'x-commandLine') { $Source += ', ``' + $P['x-commandLine'] + '``' }
        $Restart = if ((Has $P 'x-restart') -and $P['x-restart']) { Tr 'ja' 'yes' } else { Tr 'nein' 'no' }
        $Page = if (Has $P 'x-page') { Page-Text $P['x-page'] } else { '' }
        $Control = if (Has $P 'x-control') { Control-Text $P['x-control'] } else { '' }
        $Issue = if (Has $P 'x-issue') { $P['x-issue'] } else { '' }
        [void]$Table.AppendLine("| $Page | $Setting | $Default | $Source | $Restart | $(Escape $Control) | $Issue |")
    }
    foreach ($Row in $(if ($script:En) { $ExtraRowsEn } else { $ExtraRowsDe })) { [void]$Table.AppendLine($Row) }

    [void]$Table.AppendLine()
    if ($script:En) {
        [void]$Table.AppendLine('## Areas for export, import and reset')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('*Tools › Options › Atlas* and the command palette export, import and reset settings per area (#723, can be switched off with `settings.exportImport`). The area is determined by `x-area` in the schema: per plugin setting in the catalog `schemas/atlas-plugin.schema.json`, per global key in `atlas.schema.json`. New settings are thereby included without a further list. The export file `atlas-settings.json` contains only changed values, no credentials (`settings.exportSecrets`: omit or placeholder) and no paths with user names (user folders become `$(APPDATA)`, `$(LOCALAPPDATA)`, `$(USERPROFILE)`). Project and team values (`atlas.json`, `.atlas`) are neither exported nor overwritten on import.')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('| Area | Keys |')
    }
    else {
        [void]$Table.AppendLine('## Bereiche für Export, Import und Zurücksetzen')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('*Tools › Optionen › Atlas* und die Befehlspalette exportieren, importieren und setzen Einstellungen je Bereich zurück (#723, abschaltbar mit `settings.exportImport`). Den Bereich bestimmt `x-area` im Schema: je Plugin-Einstellung im Katalog `schemas/atlas-plugin.schema.json`, je globalem Schlüssel in `atlas.schema.json`. Neue Einstellungen gehören damit ohne weitere Liste dazu. Die Exportdatei `atlas-settings.json` enthält nur geänderte Werte, keine Zugangsdaten (`settings.exportSecrets`: auslassen oder Platzhalter) und keine Pfade mit Benutzernamen (Benutzerordner werden zu `$(APPDATA)`, `$(LOCALAPPDATA)`, `$(USERPROFILE)`). Projekt- und Teamwerte (`atlas.json`, `.atlas`) werden weder exportiert noch beim Import überschrieben.')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('| Bereich | Schlüssel |')
    }
    [void]$Table.AppendLine('|---|---|')
    foreach ($Area in $AreaKeys.PSBase.Keys) {
        $AreaNode = $PluginSchema['x-areas'][$Area]
        $Caption = if ($script:En -and (Has $AreaNode 'captionEn')) { $AreaNode['captionEn'] } else { $AreaNode['caption'] }
        [void]$Table.AppendLine("| $Caption (``$Area``) | $($AreaKeys[$Area] -join ', ') |")
    }
    [void]$Table.AppendLine("| $(Tr 'nicht exportiert (Zustand, nur dieser Rechner)' 'not exported (state, this machine only)') | $($Skipped -join ', ') |")
    [void]$Table.AppendLine()
    if ($script:En) {
        [void]$Table.AppendLine('## Experimental features')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('Risky or immature features come as **experimental** (#834): they have their own switch, are marked “Experimental” on the options page and in the quick switches (#604) and are off after installation. The master switch `experimental.enabled` (*Tools › Options › Atlas › General*, quick toggle “Allow experimental features”, default off) releases them: while it is off, no experimental feature works, even if its switch is on; the switches keep their value. The profile “Everything on” (#723) does not switch them on; for that there is “Everything on, including experimental”. Status panel (tooltip), bug report and diagnostic log name the effective experimental switches (keys only). When a feature becomes stable, `x-experimental` is dropped; a stored value stays.')
    }
    else {
        [void]$Table.AppendLine('## Experimentelle Funktionen')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('Riskante oder unreife Funktionen kommen als **experimentell** (#834): Sie haben einen eigenen Schalter, sind auf der Optionsseite und im Schnellschalter (#604) mit „Experimentell“ gekennzeichnet und nach der Installation aus. Der Hauptschalter `experimental.enabled` (*Tools › Optionen › Atlas › Allgemein*, Schnellschalter „Experimentelle Funktionen erlauben“, Vorgabe aus) gibt sie frei: Ist er aus, wirkt keine experimentelle Funktion, auch wenn ihr Schalter an ist; die Schalter behalten ihren Wert. Das Profil „Alles an“ (#723) schaltet sie nicht ein, dafür gibt es „Alles an, auch experimentell“. Statusfeld (Tooltip), Fehlerbericht und Diagnoselog nennen die wirksamen experimentellen Schalter (nur Schlüssel). Wird eine Funktion stabil, fällt `x-experimental` weg; ein gespeicherter Wert bleibt.')
    }
    [void]$Table.AppendLine()
    if (($ServerExperimental.Count + $PluginExperimental.Count) -eq 0) { [void]$Table.AppendLine((Tr 'Zurzeit ist keine Funktion experimentell.' 'Currently no feature is experimental.')) }
    else {
        [void]$Table.AppendLine((Tr '| Schlüssel | Ort | Seite | Herkunft |' '| Key | Place | Page | Origin |'))
        [void]$Table.AppendLine('|---|---|---|---|')
        foreach ($Name in $PluginExperimental) {
            $P = $PluginSchema['properties'][$Name]
            $Issue = if (Has $P 'x-issue') { $P['x-issue'] } else { '' }
            $Registry = Tr 'Registry' 'registry'
            [void]$Table.AppendLine("| ``$($P['x-key'])`` | Plugin ($Registry ``$Name``) | $(Page-Text $P['x-page']) | $Issue |")
        }
        foreach ($Path in $ServerExperimental) {
            $Parts = $Path.Split('.')
            $P = $Schema['properties'][$Parts[0]]
            $Node = if ($Parts.Count -gt 1) { $P['properties'][$Parts[1]] } else { $P }
            $Issue = if (Has $Node 'x-issue') { $Node['x-issue'] } elseif (Has $P 'x-issue') { $P['x-issue'] } else { '' }
            $Place = if ($Parts.Count -gt 1) { Scope-Of $Node (Scope-Of $P '') } else { Scope-Of $P '' }
            [void]$Table.AppendLine("| ``$Path`` | $(Scope-Text $Place) | $(Page-Text $P['x-page']) | $Issue |")
        }
    }
    [void]$Table.AppendLine()
    if ($script:En) {
        [void]$Table.AppendLine('## Options page: sub-items and master switches')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('*Tools › Options › Atlas* shows a tree on the left (#890): the areas at the top, below them the sub-items per feature. The main node of an area carries its general options and an overview of all master switches of its sub-items (with “Details”). Every feature with a master switch has its own frame, the switch at the top, the sub-options indented below. While a master switch is off, all controls of its group are disabled (also nested groups); the values are kept and saved as well. Experimental features including their master switch are disabled as long as `experimental.enabled` is off. The master switch is determined by `x-parent` in the plugin catalog, otherwise by the prefix rule (longest prefix `P` with a Boolean setting `P` or `P.enabled`); the sub-item by `x-node` (IDs in `x-nodes`), otherwise the sub-item of the master switch. Structured by page (`x-page`) and sub-item; indented = sub-option of the switch above.')
    }
    else {
        [void]$Table.AppendLine('## Optionsseite: Unterpunkte und Hauptschalter')
        [void]$Table.AppendLine()
        [void]$Table.AppendLine('*Tools › Optionen › Atlas* zeigt links einen Baum (#890): oben die Bereiche, darunter die Unterpunkte je Funktion. Der Hauptknoten eines Bereichs trägt dessen allgemeine Optionen und eine Übersicht aller Hauptschalter seiner Unterpunkte (mit „Details“). Jede Funktion mit Hauptschalter steht in einem eigenen Rahmen, der Schalter oben, die Unteroptionen eingerückt darunter. Ist ein Hauptschalter aus, sind alle Bedienelemente seiner Gruppe gesperrt (auch verschachtelte Gruppen); die Werte bleiben erhalten und werden mit gespeichert. Experimentelle Funktionen samt Hauptschalter sind gesperrt, solange `experimental.enabled` aus ist. Den Hauptschalter bestimmt `x-parent` im Plugin-Katalog, sonst die Präfixregel (längstes Präfix `P` mit boolescher Einstellung `P` oder `P.enabled`); den Unterpunkt `x-node` (Kennungen in `x-nodes`), sonst der Unterpunkt des Hauptschalters. Gliederung nach Seite (`x-page`) und Unterpunkt; eingerückt = Unteroption des Schalters darüber.')
    }
    foreach ($Page in $PageOrder) {
        [void]$Table.AppendLine()
        [void]$Table.AppendLine("### $(Page-Text $Page)")
        $Nodes = @('') + @($NodeTable.Keys | Where-Object { $NodePages[$_] -ceq $Page })
        foreach ($Node in $Nodes) {
            $GroupRoots = @($PluginProps.Keys | Where-Object {
                ($PluginProps[$_]['x-page'] -ceq $Page) -and ((Node-Of $_) -ceq $Node) -and
                -not ((Has $PluginProps[$_] 'x-state') -and $PluginProps[$_]['x-state']) -and
                (($Parents[$_] -eq '') -or ((Node-Of $Parents[$_]) -cne $Node) -or ($PluginProps[$Parents[$_]]['x-page'] -cne $Page)) })
            if ($GroupRoots.Count -eq 0) { continue }
            [void]$Table.AppendLine()
            if ($Node -eq '') { [void]$Table.AppendLine((Tr '- **Hauptknoten**' '- **Main node**')) }
            else {
                $NodeCaption = if ($script:En -and (Has $NodeTable[$Node] 'captionEn')) { $NodeTable[$Node]['captionEn'] } else { $NodeTable[$Node]['caption'] }
                [void]$Table.AppendLine("- **$NodeCaption** (``$Node``)")
            }
            foreach ($GroupRoot in $GroupRoots) { Write-Group $GroupRoot $Node 1 }
        }
    }
    return $Table.ToString().Replace("`r`n", "`n")
}
