# --- Wächter: Schlüssel im Parser ---
$Problems = New-Object System.Collections.Generic.List[string]
foreach ($Issue in $GroupIssues) { $Problems.Add($Issue) }
$SchemaKeys = @($Schema['properties'].Keys | Where-Object { $_ -ne '$schema' } | Sort-Object)
# Jeder Schlüssel der obersten Ebene ist ein Abschnitt (Section: '…') in einer der Units
# Internals/*Options.pas; der Abschnitt liest (Read) und schichtet (Take).
$OptionPaths = @(Get-ChildItem -Path (Join-Path (Split-Path $ParserPath) 'Internals') -Filter 'Atlas.Common.Configuration.Internals.*Options.pas' | Sort-Object Name | ForEach-Object { $_.FullName })
$ParserText = (@($ParserPath) + $OptionPaths | ForEach-Object { [IO.File]::ReadAllText($_, $Utf8) }) -join "`n"
$ParserText = $ParserText.Replace("`r`n", "`n")
$Keys = @([regex]::Matches($ParserText, "Section: '([A-Za-z]+)'") | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
if ($Keys.Count -eq 0) { $Problems.Add('Parser: keine Abschnitte in Internals/*Options.pas gefunden') }
foreach ($Key in $SchemaKeys) { if ($Keys -cnotcontains $Key) { $Problems.Add("Parser: Abschnitt ""$Key"" aus dem Schema fehlt") } }
foreach ($Key in $Keys) { if ($SchemaKeys -cnotcontains $Key) { $Problems.Add("Parser: Abschnitt ""$Key"" fehlt im Schema") } }
foreach ($Name in $SchemaKeys) {
    $P = $Schema['properties'][$Name]
    if (Has $P 'properties') {
        foreach ($Sub in $P['properties'].Keys) {
            if (-not $ParserText.Contains("'$Sub'")) { $Problems.Add("Parser: ""$Name.$Sub"" aus dem Schema wird nicht gelesen") }
        }
    }
    foreach ($Meta in 'x-page', 'x-control', 'x-issue', 'x-scope') {
        if (-not (Has $P $Meta)) { $Problems.Add("Schema: ""$Name"" ohne $Meta") }
    }
    if ((Has $P 'x-scope') -and ('global', 'project', 'both' -cnotcontains $P['x-scope'])) { $Problems.Add("Schema: ""$Name"" mit x-scope ""$($P['x-scope'])""; erlaubt sind global, project und both") }
    if (Has $P 'properties') {
        foreach ($Sub in $P['properties'].Keys) {
            $S = $P['properties'][$Sub]
            if ((Has $S 'x-scope') -and ('global', 'project' -cnotcontains $S['x-scope'])) { $Problems.Add("Schema: ""$Name.$Sub"" mit x-scope ""$($S['x-scope'])""; erlaubt sind global und project") }
        }
    }
}

# --- Wächter: englische Beschreibungen (#1458) ---
function Check-English([string] $Where, $Node) {
    if ($Node -is [System.Collections.IDictionary]) {
        if ((Has $Node 'description') -and ($Node['description'] -is [string]) -and
            -not ((Has $Node 'x-description-en') -and ([string]$Node['x-description-en']).Trim() -ne '')) {
            $Problems.Add("Schema: ""$Where"" ohne x-description-en (englische Beschreibung, #1458)")
        }
        foreach ($Key in @($Node.Keys)) { if ($Key -ne 'x-description-en') { Check-English "$Where/$Key" $Node[$Key] } }
    }
    elseif (($Node -is [System.Collections.IList]) -and -not ($Node -is [string])) {
        for ($Index = 0; $Index -lt $Node.Count; $Index++) { Check-English "$Where[$Index]" $Node[$Index] }
    }
}
Check-English '' $Schema

# --- Wächter: Katalog der Plugin-Einstellungen (#723) ---
# Jeder Wert steht genau einmal in Exchange seines Bereichs: AIo.Flag/Number/Text/TrimmedText('Name', …).
$SaveNames = [Collections.Generic.List[string]]::new()
$CatalogNames = @($PluginSchema['properties'].Keys)
foreach ($AreaFile in Get-ChildItem -Path $PluginFolder -Filter 'Atlas.Core.Settings.Plugin.*.pas') {
    $AreaUnit = $AreaFile.BaseName.Substring('Atlas.Core.Settings.Plugin.'.Length)
    $AreaText = [IO.File]::ReadAllText($AreaFile.FullName, $Utf8)
    foreach ($Match in [regex]::Matches($AreaText, "AIo\.(?:Flag|Number|Text|TrimmedText)\('(\w+)'")) {
        $Name = $Match.Groups[1].Value
        $SaveNames.Add($Name)
        if (-not ($CatalogNames -ccontains $Name) -or -not (Has $PluginSchema['properties'][$Name] 'x-area')) { continue }
        $Area = [string]$PluginSchema['properties'][$Name]['x-area']
        if (($Area.Substring(0, 1).ToUpperInvariant() + $Area.Substring(1)) -cne $AreaUnit) {
            $Problems.Add("Plugin-Katalog: ""$Name"" steht in Atlas.Core.Settings.Plugin.$AreaUnit, gehört nach x-area ""$Area""")
        }
    }
}
foreach ($Twice in @($SaveNames | Group-Object | Where-Object Count -gt 1)) { $Problems.Add("Plugin-Katalog: ""$($Twice.Name)"" wird mehrfach gelesen und geschrieben") }
foreach ($Name in $SaveNames) { if ($CatalogNames -cnotcontains $Name) { $Problems.Add("Plugin-Katalog: ""$Name"" aus TAtlasPluginSettings (Exchange der Bereiche) fehlt in schemas/atlas-plugin.schema.json") } }
foreach ($Name in $CatalogNames) { if ($SaveNames -cnotcontains $Name) { $Problems.Add("Plugin-Katalog: ""$Name"" wird in TAtlasPluginSettings (Exchange der Bereiche) nicht gelesen und geschrieben") } }
$SeenKeys = @{}
foreach ($Name in $CatalogNames) {
    $P = $PluginSchema['properties'][$Name]
    foreach ($Meta in 'type', 'default', 'x-key', 'x-area', 'x-page') {
        if (-not $P.ContainsKey($Meta)) { $Problems.Add("Plugin-Katalog: ""$Name"" ohne $Meta") }
    }
    if ((Has $P 'x-area') -and -not $PluginSchema['x-areas'].Contains($P['x-area'])) { $Problems.Add("Plugin-Katalog: ""$Name"" mit unbekanntem Bereich ""$($P['x-area'])""") }
    if (Has $P 'x-key') {
        if ($SeenKeys.ContainsKey($P['x-key'])) { $Problems.Add("Plugin-Katalog: x-key ""$($P['x-key'])"" doppelt ($($SeenKeys[$P['x-key']]), $Name)") }
        else { $SeenKeys[$P['x-key']] = $Name }
    }
}
foreach ($Name in $Schema['properties'].Keys) {
    if ($Name -eq '$schema') { continue }
    $P = $Schema['properties'][$Name]
    $Scope = Scope-Of $P ''
    if (('global', 'both' -ccontains $Scope) -and -not (Has $P 'x-area')) { $Problems.Add("Schema: globaler Schlüssel ""$Name"" ohne x-area (Bereich für Export und Import, #723)") }
    if ((Has $P 'x-area') -and -not $PluginSchema['x-areas'].Contains($P['x-area'])) { $Problems.Add("Schema: ""$Name"" mit unbekanntem Bereich ""$($P['x-area'])""") }
    if (Has $P 'properties') {
        foreach ($Sub in $P['properties'].Keys) {
            $S = $P['properties'][$Sub]
            if (('global', 'both' -ccontains (Scope-Of $S $Scope)) -and -not (Has $S 'x-area') -and -not (Has $P 'x-area')) { $Problems.Add("Schema: globaler Schlüssel ""$Name.$Sub"" ohne x-area") }
            if ((Has $S 'x-area') -and -not $PluginSchema['x-areas'].Contains($S['x-area'])) { $Problems.Add("Schema: ""$Name.$Sub"" mit unbekanntem Bereich ""$($S['x-area'])""") }
        }
    }
}

# --- Wächter: experimentelle Funktionen (#834) ---
function Check-Experimental([string] $Where, [hashtable] $Node) {
    if (-not (Is-Experimental $Node)) { return }
    if (Has $Node 'properties') { $Problems.Add("${Where}: x-experimental gehört an die einzelnen Einstellungen, nicht an das Objekt"); return }
    if (-not $Node.ContainsKey('default')) { $Problems.Add("${Where}: experimentell (x-experimental) ohne default; die Vorgabe muss aus sein"); return }
    $Off = if ($Node.ContainsKey('x-offValue')) { $Node['x-offValue'] } else { $false }
    if ((ConvertTo-Json -InputObject $Node['default'] -Compress) -cne (ConvertTo-Json -InputObject $Off -Compress)) {
        $Problems.Add("${Where}: experimentell (x-experimental), aber Vorgabe $(Format-Value $Node['default']) statt aus ($(Format-Value $Off))")
    }
}
foreach ($Name in $Schema['properties'].Keys) {
    if ($Name -eq '$schema') { continue }
    $P = $Schema['properties'][$Name]
    Check-Experimental "Schema ""$Name""" $P
    if (Has $P 'properties') { foreach ($Sub in $P['properties'].Keys) { Check-Experimental "Schema ""$Name.$Sub""" $P['properties'][$Sub] } }
}
foreach ($Name in $PluginSchema['properties'].Keys) { Check-Experimental "Plugin-Katalog ""$Name""" $PluginSchema['properties'][$Name] }
if ($ServerExperimental -ccontains $MasterPath) { $Problems.Add("Schema: der Hauptschalter ""$MasterPath"" darf nicht selbst experimentell sein") }
foreach ($Name in $PluginExperimental) { if ($PluginSchema['properties'][$Name]['x-key'] -ceq $MasterPath) { $Problems.Add("Plugin-Katalog: der Hauptschalter ""$Name"" darf nicht selbst experimentell sein") } }
# Profile sind globale Einstellungen: Server-Schlüssel nur mit x-scope global oder both (eigenes oder das des
# Abschnitts); reine Projektwerte (etwa refactoring.*) stehen in keinem Profil, wie im Katalog des Plugins.
function Profile-Scope-Of([string] $Key) {
    $Parts = $Key.Split('.')
    $Top = $Schema['properties'][$Parts[0]]
    $Scope = ''
    if (Has $Top 'x-scope') { $Scope = $Top['x-scope'] }
    if ($Parts.Count -gt 1) {
        $Member = $Top['properties'][$Parts[1]]
        if (Has $Member 'x-scope') { $Scope = $Member['x-scope'] }
    }
    return $Scope
}
$ProfileServerExperimental = @($ServerExperimental | Where-Object { (Profile-Scope-Of $_) -in @('global', 'both') })
$ExperimentalKeys = @($PluginExperimental | ForEach-Object { $PluginSchema['properties'][$_]['x-key'] }) + @($ProfileServerExperimental)
# Ausgeschaltet ist false bzw. x-offValue (Aufzählungen wie "off"); eingeschaltet jeder andere Wert.
function Off-Value-Of([string] $Key) {
    foreach ($Name in $PluginSchema['properties'].Keys) {
        $N = $PluginSchema['properties'][$Name]
        if ($N['x-key'] -ceq $Key) { if ($N.ContainsKey('x-offValue')) { return $N['x-offValue'] }; return $false }
    }
    $N = $Schema
    foreach ($Part in $Key.Split('.')) {
        if (-not ((Has $N 'properties') -and $N['properties'].ContainsKey($Part))) { return $false }
        $N = $N['properties'][$Part]
    }
    if ($N.ContainsKey('x-offValue')) { return $N['x-offValue'] }
    return $false
}
function Is-On([string] $Key, $Value) {
    if ($null -eq $Value) { return $false }
    if ($Value -is [bool]) { return $Value }
    return (ConvertTo-Json -InputObject $Value -Compress) -cne (ConvertTo-Json -InputObject (Off-Value-Of $Key) -Compress)
}
